SELECT id, practice_script->>'version' AS version, md5(practice_script::text) AS huella FROM public.nodes WHERE id IN ('2.8','3.9','3.9b','4.2','4.6','4.8','4.9','4.10','4.15','4.14','4.16','5.6','5.8','5.10','5.12','5.15','7.2','7.4') ORDER BY id;
SELECT id, md5(concat_ws('|', paso, tipo, canal, procedencia, resumen, cita_cerebro, severidad_default)) AS huella FROM public.reglas WHERE id IN ('impulse.avaricia','impulse.efecto_jones','impulse.escasez_inventada','impulse.factores','impulse.indiferencia','impulse.indiferencia_teatral','impulse.jones_vago','impulse.miedo_perdida','impulse.miedo_perdida_generico','impulse.presion_directa','impulse.ruega','impulse.tren_del_si','impulse.urgencia','present.argumento_del_hueco','present.ataca_proveedor','present.bala_generica','present.balas','present.beneficio_no_caracteristica','present.caracteristica_sin_traducir','present.dos_mitades','present.dosificacion_balas','present.escalon_sin_motivo','present.garantiza','present.pide_que_pruebe','present.pintar_imagenes','present.plan_b','present.precio_unico','present.triple_desglose') ORDER BY id;
SELECT node_id, card_order, md5(body) AS huella FROM public.node_cards WHERE node_id = '4.7' AND card_order IN (4, 6) ORDER BY card_order;
SELECT max(version) AS version_cerebro, count(*) AS secciones, md5(string_agg(body, '#' ORDER BY order_index)) AS huella_cerebro FROM public.doctrina WHERE is_active;
